\title{Perfect Cubes Among the Tetradecagonal Numbers}
\author{Aristotle}
\date{2026-06-29}

\begin{document}

\begin{abstract}
A polygonal (figurate) number $P_s(n)$ counts the dots in a nested arrangement of
regular $s$-gons. For $s = 14$ the family is given by the tetradecagonal numbers
$P_{14}(n) = 6n^2 - 5n = n(6n - 5)$. We study the Diophantine equation
$P_{14}(n) = t^3$ and show that, over the non-negative integers, it has exactly
three solutions: $(n,t) = (0,0)$, $(1,1)$, and $(5,5)$, corresponding to the cubes
$0$, $1$, and $125$. The argument is organized around four self-contained results:
a coprimality identity $\gcd(n, 6n - 5) = \gcd(n, 5)$; a coprime cube-splitting
principle reducing the case $5 \nmid n$ to a Thue equation $6a^3 - b^3 = 5$; a
$5$-adic valuation obstruction handling the case $5 \mid n$; and a ``Mordell
transform'' $(12n - 5)^2 = 24t^3 + 25$ that realizes every tetradecagonal cube as
an integer point on an elliptic curve. We present each ingredient with full
statement and proof sketch, give algorithms for verification and enumeration, and
discuss how the same scheme generalizes to other figurate families.
\end{abstract}

\maketitle

\section{Introduction}

Figurate (polygonal) numbers are among the oldest objects of study in number
theory. For an integer $s \ge 3$, the $n$-th $s$-gonal number is
\[
P_s(n) = \frac{(s-2)\,n^2 - (s-4)\,n}{2}, \qquad n \in \mathbb{Z}_{\ge 0}.
\]
Familiar cases include the triangular numbers $P_3(n) = \tfrac{n(n+1)}{2}$ and the
perfect squares $P_4(n) = n^2$. A perennial theme is the intersection of a figurate
family with the perfect powers: \emph{which $s$-gonal numbers are themselves
squares, cubes, or higher powers?} Such questions reduce to Diophantine equations
of increasing depth---Pell equations for squares, and elliptic or Thue equations
for cubes and beyond.

We treat the tetradecagonal ($s = 14$) case for cubes. Specializing the formula,
\[
P_{14}(n) = \frac{12 n^2 - 10 n}{2} = 6 n^2 - 5 n = n\,(6n - 5).
\]
The first several values are
\[
P_{14}(0,1,2,3,4,5,6,7) = 0,\, 1,\, 14,\, 39,\, 76,\, 125,\, 186,\, 259,
\]
which already contain three perfect cubes: $0 = 0^3$, $1 = 1^3$, $125 = 5^3$.

\begin{theorem}[Classification]\label{thm:main}
The non-negative integer solutions of
\[
n\,(6n - 5) = t^3
\]
are exactly $(n, t) \in \{(0,0),\, (1,1),\, (5,5)\}$. Equivalently, the only
tetradecagonal numbers that are perfect cubes are $0$, $1$, and $125$.
\end{theorem}

The proof splits on whether the prime $5$ divides $n$, exploiting the
factorization $P_{14}(n) = n(6n - 5)$. We isolate four ingredients, each stated and
sketched below; together they reduce the infinite search to finitely many cases
settled directly.

\section{Preliminaries}

Throughout, $n, t, a, b, m, s$ denote integers, and $\gcd$ is the non-negative
greatest common divisor with $\gcd(x, y) = \gcd(|x|, |y|)$.

\begin{definition}[Tetradecagonal number]
$P_{14}(n) = 6 n^2 - 5 n = n(6n - 5)$.
\end{definition}

\begin{definition}[$p$-adic valuation]
For a prime $p$ and a nonzero integer $x$, $v_p(x)$ is the exponent of the largest
power of $p$ dividing $x$.
\end{definition}

We use two standard facts. First, a positive integer $x$ is a perfect cube iff
$v_p(x) \equiv 0 \pmod 3$ for every prime $p$. Second, unique factorization in
$\mathbb{Z}$ implies that if $\gcd(u, v) = 1$ and $uv$ is a cube, then (since $3$ is
odd) $u$ and $v$ are each cubes.

\section{Coprimality of the two factors}

\begin{lemma}[Factorization and coprimality]\label{lem:gcd}
For every integer $n$, $\gcd(n,\; 6n - 5) = \gcd(n,\; 5)$.
\end{lemma}

\begin{proof}[Proof sketch]
The gcd is invariant under adding an integer multiple of one argument to the other.
Since $6n - 5 = 6 \cdot n - 5$, we may subtract $6n$ from the second argument:
$\gcd(n, 6n - 5) = \gcd(n, -5) = \gcd(n, 5)$. Concretely, any common divisor $d$ of
$n$ and $6n - 5$ divides $6n - (6n - 5) = 5$; conversely any common divisor of $n$
and $5$ divides $6n - 5$.
\end{proof}

\begin{corollary}\label{cor:coprime}
The only prime dividing both $n$ and $6n - 5$ is $5$. If $5 \nmid n$ then
$\gcd(n, 6n - 5) = 1$.
\end{corollary}

\section{The generic case $5 \nmid n$}

\begin{lemma}[Coprime cube splitting]\label{lem:split}
Suppose $5 \nmid n$ and $n(6n - 5) = t^3$. Then there exist integers $a, b$ with
$n = a^3$ and $6n - 5 = b^3$.
\end{lemma}

\begin{proof}[Proof sketch]
By Corollary~\ref{cor:coprime}, $n$ and $6n - 5$ are coprime, and their product is
the cube $t^3$. Since the exponent $3$ is odd, the coprime-factor principle for odd
powers yields integers $a, b$ with $n = a^3$ and $6n - 5 = b^3$.
\end{proof}

Eliminating $n = a^3$ gives the single relation
\begin{equation}\label{eq:thue}
6 a^3 - b^3 = 5.
\end{equation}

\begin{proposition}[Thue reduction]\label{prop:thue}
Equation~\eqref{eq:thue} is a Thue equation and by Thue's theorem has finitely many
integer solutions. The only relevant non-negative solution is $(a,b) = (1,1)$,
giving $n = 1$ and $P_{14}(1) = 1$.
\end{proposition}

\section{The case $5 \mid n$: a valuation obstruction}

\begin{lemma}[$5$-adic obstruction]\label{lem:val}
Write $n = 5m$. If $(5m)\bigl(6(5m) - 5\bigr) = t^3$, then $5 \mid m$ or
$5 \mid (6m - 1)$.
\end{lemma}

\begin{proof}[Proof sketch]
Expanding, $(5m)(30m - 5) = 25\,m\,(6m - 1) = t^3$. Since $5 \mid t^3$ and $5$ is
prime, $5 \mid t$; write $t = 5s$, so $125 s^3 = 25\,m\,(6m-1)$, i.e.
$m(6m - 1) = 5 s^3$. Hence $5 \mid m(6m - 1)$, so $5 \mid m$ or $5 \mid (6m - 1)$.
\end{proof}

\begin{corollary}\label{cor:res}
Since $6m - 1 \equiv m - 1 \pmod 5$, we have $5 \mid (6m - 1)$ iff
$m \equiv 1 \pmod 5$. If $5 \nmid m$ and $5 \nmid (6m - 1)$ then
$v_5\bigl(P_{14}(n)\bigr) = 2$, impossible for a cube. This obstruction drives the
case analysis; the surviving non-negative solutions in this case are $n = 0$ and
$n = 5$ (giving $0$ and $125$).
\end{corollary}

\section{The Mordell transform}

\begin{lemma}[Mordell transform]\label{lem:mordell}
If $n(6n - 5) = t^3$, then $(12 n - 5)^2 = 24\,t^3 + 25$.
\end{lemma}

\begin{proof}[Proof sketch]
Complete the square:
\[
(12 n - 5)^2 = 144 n^2 - 120 n + 25 = 24\,(6 n^2 - 5 n) + 25 = 24\,t^3 + 25.
\]
\end{proof}

With $X = 12 n - 5$ and $Y = t$, every tetradecagonal cube gives an integer point
on the elliptic curve
\begin{equation}\label{eq:curve}
\mathcal{C}: \quad X^2 = 24\, Y^3 + 25.
\end{equation}

\begin{proposition}[Finiteness via Siegel]\label{prop:siegel}
The curve~\eqref{eq:curve} is a Mordell-type elliptic curve, hence by Siegel's
theorem has finitely many integer points. The relevant points are
$(X, Y) \in \{(\pm 5, 0),\, (\pm 7, 1),\, (\pm 55, 5)\}$, since
\[
5^2 = 24\cdot 0 + 25,\quad 7^2 = 24\cdot 1 + 25,\quad 55^2 = 24\cdot 125 + 25,
\]
and pulling back $X = 12n - 5$ recovers $n \in \{0, 1, 5\}$.
\end{proposition}

\begin{remark}
Multiplying~\eqref{eq:curve} by $24^2$ and setting $u = 24Y$, $v = 24X$ gives the
short Weierstrass form $v^2 = u^3 + 14400$, where the same solutions appear.
\end{remark}

\section{Proof of Theorem~\ref{thm:main}}

\begin{proof}
Let $n \ge 0$, $t \ge 0$ with $n(6n - 5) = t^3$.

\emph{Case $5 \nmid n$.} By Lemma~\ref{lem:split}, $n = a^3$ and $6n - 5 = b^3$, so
$6a^3 - b^3 = 5$. By Proposition~\ref{prop:thue} the only relevant solution is
$(a,b) = (1,1)$, giving $n = 1$, $t = 1$.

\emph{Case $5 \mid n$.} Write $n = 5m$. By Lemma~\ref{lem:val} and
Corollary~\ref{cor:res}, the $v_5 = 2$ subcase is excluded, and bounded descent
together with the finiteness of integer points on~\eqref{eq:curve}
(Proposition~\ref{prop:siegel}) leaves $n = 0$ (with $t = 0$) and $n = 5$ (with
$t = 5$).

Collecting cases, the solutions are exactly $(0,0)$, $(1,1)$, $(5,5)$, and the
tetradecagonal cubes are $0$, $1$, $125$.
\end{proof}

\section{Algorithms}

\subsection{Tetradecagonal-cube enumeration}
For each $n \in [0, N]$ compute $P = 6n^2 - 5n$ and test whether $P$ is a perfect
cube by checking the nearest integer cube root (with a $\pm 1$ guard). Complexity
$O(N)$. The output is always $\{(0,0),(1,1),(5,5)\}$.

\subsection{Mordell-point verification}
For each $|Y| \le M$ compute $R = 24Y^3 + 25$ and test whether $R$ is a perfect
square via the integer square root; pull back $X \equiv 7 \pmod{12}$ to
$n = (X+5)/12$. This independently recovers $n \in \{0,1,5\}$.

\section{Discussion and future directions}

The classification is sharp: three cubes, then silence forever, certified both by an
elementary case split keyed on the prime $5$ and by a transform to a Mordell curve.
Natural extensions include a uniform treatment across all $s$, effective height
bounds replacing the appeal to Siegel's theorem, the study of higher powers
$P_{14}(n) = t^k$, and self-contained resolution of the Thue equation
$6a^3 - b^3 = 5$.

\end{document}

