from __future__ import annotations
from typing import List, Tuple


def tetradecagonal(n: int) -> int:
    """The n-th tetradecagonal number P_14(n) = 6n^2 - 5n."""
    return 6 * n * n - 5 * n


def integer_cube_root(x: int) -> "int | None":
    """Return t with t^3 == x if it exists, else None (for x >= 0)."""
    if x < 0:
        return None
    t = round(x ** (1.0 / 3.0)) if x > 0 else 0
    for c in (t - 1, t, t + 1):
        if c >= 0 and c * c * c == x:
            return c
    return None


def tetradecagonal_cubes(bound: int) -> List[Tuple[int, int]]:
    """All (n, t) with 0 <= n <= bound and P_14(n) = t^3."""
    out: List[Tuple[int, int]] = []
    for n in range(bound + 1):
        t = integer_cube_root(tetradecagonal(n))
        if t is not None:
            out.append((n, t))
    return out


if __name__ == "__main__":
    print(tetradecagonal_cubes(100000))   # -> [(0, 0), (1, 1), (5, 5)]

from __future__ import annotations
from math import isqrt
from typing import List, Tuple


def tetradecagonal(n: int) -> int:
    return 6 * n * n - 5 * n


def is_perfect_square(x: int) -> bool:
    if x < 0:
        return False
    r = isqrt(x)
    return r * r == x


def mordell_points(y_bound: int) -> List[Tuple[int, int]]:
    """Integer points (X, Y) on X^2 = 24 Y^3 + 25 with |Y| <= y_bound."""
    pts: List[Tuple[int, int]] = []
    for y in range(-y_bound, y_bound + 1):
        r = 24 * y ** 3 + 25
        if r >= 0 and is_perfect_square(r):
            x = isqrt(r)
            pts.append((x, y))
            if x != 0:
                pts.append((-x, y))
    return pts


def recover_n(y_bound: int) -> List[int]:
    """Pull back integer points to n = (X + 5)/12 when X = 7 (mod 12)."""
    ns = set()
    for x, y in mordell_points(y_bound):
        if (x + 5) % 12 == 0:
            n = (x + 5) // 12
            if n >= 0 and y >= 0 and tetradecagonal(n) == y ** 3:
                ns.add(n)
    return sorted(ns)


if __name__ == "__main__":
    print(recover_n(50))   # -> [0, 1, 5]

